-- Deployment gate: an authenticated workspace member can only start a deployment after approval and with no failed policy evaluation.
create or replace function public.create_deployment_for_approved_change(p_change uuid,p_provider text default null) returns uuid language plpgsql security definer set search_path=public as $$declare c public.change_requests;a boolean;bad boolean;d uuid;begin select * into c from public.change_requests where id=p_change and public.is_workspace_member(workspace_id);if c.id is null then raise exception 'change not found';end if;select exists(select 1 from public.approvals where change_request_id=p_change and status='approved') into a;select exists(select 1 from public.policy_evaluations where change_request_id=p_change and result='fail') into bad;if not a then raise exception 'approved decision required';end if;if bad then raise exception 'blocking policy failure';end if;insert into public.deployments(workspace_id,project_id,environment_id,change_request_id,validation_id,status,provider,started_at) values(c.workspace_id,c.project_id,c.environment_id,c.id,c.validation_id,'running',p_provider,now()) returning id into d;update public.change_requests set status='approved',updated_at=now() where id=p_change;return d;end$$;revoke all on function public.create_deployment_for_approved_change(uuid,text) from public;grant execute on function public.create_deployment_for_approved_change(uuid,text) to authenticated;